void mapPowersOfTwo(std::vector<int> const& x, std::vector<bool> &mask) {
    // Avoid parallel writes to std::vector<bool> (bit-packed). Use a temp buffer.
    std::vector<unsigned char> tmp(x.size());
    hpx::transform(hpx::execution::par, x.begin(), x.end(), tmp.begin(),
        [](int v) { return static_cast<unsigned char>(isPowerOfTwo(v)); });
    mask.assign(tmp.begin(), tmp.end());
}

